import React, { useState, useEffect, useMemo } from "react";
import piece_01 from "./assets/mistermoon_01.png";
import piece_02 from "./assets/mistermoon_02.png";
import piece_03 from "./assets/mistermoon_03.png";
import piece_04 from "./assets/mistermoon_04.png";
import piece_05 from "./assets/mistermoon_05.png";
import piece_06 from "./assets/mistermoon_06.png";
import piece_07 from "./assets/mistermoon_07.png";
import piece_08 from "./assets/mistermoon_08.png";
import piece_09 from "./assets/mistermoon_09.png";
import piece_10 from "./assets/mistermoon_10.png";
import piece_11 from "./assets/mistermoon_11.png";
import piece_12 from "./assets/mistermoon_12.png";
import piece_13 from "./assets/mistermoon_13.png";
import piece_14 from "./assets/mistermoon_14.png";
import piece_15 from "./assets/mistermoon_15.png";
import piece_16 from "./assets/mistermoon_16.png";

const PIECES = [
  piece_01,
  piece_02,
  piece_03,
  piece_04,
  piece_05,
  piece_06,
  piece_07,
  piece_08,
  piece_09,
  piece_10,
  piece_11,
  piece_12,
  piece_13,
  piece_14,
  piece_15,
  piece_16,
];

// --- Configuration ---
const GRID_SIZE = 4;
const TILE_COUNT = GRID_SIZE * GRID_SIZE;

// --- Helper Functions ---

/**
 * Generates a solved puzzle array.
 * @returns {number[]} An array from 1 to 16.
 */
const createSolvedArray = () => [...Array(TILE_COUNT).keys()].map((i) => i + 1);

/**
 * Shuffles an array using the Fisher-Yates algorithm and ensures it's solvable.
 * @param {number[]} array The array to shuffle.
 * @returns {number[]} The shuffled and solvable array.
 */
const shuffleArray = (array: number[]): number[] => {
  const shuffled = [...array];
  for (let i = shuffled.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
  }
  return shuffled;
};

// Defines the props for the SwapPuzzle component.
type SwapPuzzleProps = {
  onVerify: (isVerified: boolean) => void;
};

/**
 * Main App Component for the SwapPuzzle.
 */
export const SwapPuzzle: React.FC<SwapPuzzleProps> = ({ onVerify }) => {
  const SOLVED_ARRAY = useMemo(() => createSolvedArray(), []);
  const [tiles, setTiles] = useState(() => {
    console.log("--- INITIALIZING STATE (This should only run ONCE) ---");
    return shuffleArray([...SOLVED_ARRAY]);
  });
  const [isSolved, setIsSolved] = useState(false);
  const [selectedTileIndex, setSelectedTileIndex] = useState<number | null>(
    null,
  );

  /**
   * Handles the shuffling of the puzzle tiles.
   */
  const handleShuffle = () => {
    setSelectedTileIndex(null); // Deselect any tile on shuffle
    setTiles(shuffleArray([...SOLVED_ARRAY]));
  };

  // Effect to check for the win condition whenever the tiles change.
  useEffect(() => {
    const checkSolved = tiles.every((t, i) => t === SOLVED_ARRAY[i]);
    if (checkSolved) {
      setIsSolved(checkSolved);
      onVerify(true);
      console.log("Puzzle solved!");
    }
  }, [tiles, SOLVED_ARRAY, onVerify]);

  /**
   * Handles the click event on a tile.
   * Manages selecting a tile and swapping it with an adjacent tile.
   * @param {number} clickedIndex The index of the clicked tile.
   */
  const handleTileClick = (clickedIndex: number) => {
    if (isSolved) return; // Don't allow moves if the puzzle is already solved.

    if (selectedTileIndex === null) {
      // This is the first tile being selected.
      setSelectedTileIndex(clickedIndex);
    } else {
      // A tile is already selected, this is the second tile.
      if (selectedTileIndex === clickedIndex) {
        // If the user clicks the same tile again, deselect it.
        setSelectedTileIndex(null);
        return;
      }

      const { row: selectedRow, col: selectedCol } =
        getMatrixPosition(selectedTileIndex);
      const { row: clickedRow, col: clickedCol } =
        getMatrixPosition(clickedIndex);

      // Check if the clicked tile is adjacent to the selected tile.
      const isAdjacent =
        (Math.abs(selectedRow - clickedRow) === 1 &&
          selectedCol === clickedCol) ||
        (Math.abs(selectedCol - clickedCol) === 1 &&
          selectedRow === clickedRow);

      if (isAdjacent) {
        // If they are adjacent, swap them.
        const newTiles = [...tiles];
        [newTiles[selectedTileIndex], newTiles[clickedIndex]] = [
          newTiles[clickedIndex],
          newTiles[selectedTileIndex],
        ];
        setTiles(newTiles);
        setSelectedTileIndex(null); // Reset selection after swap.
      } else {
        // If they are not adjacent, just select the new tile.
        setSelectedTileIndex(clickedIndex);
      }
    }
  };

  /**
   * Converts a 1D array index to a 2D grid position (row, col).
   * @param {number} index The index in the 1D array.
   * @returns {{row: number, col: number}} The position in the grid.
   */
  const getMatrixPosition = (index: number) => ({
    row: Math.floor(index / GRID_SIZE),
    col: index % GRID_SIZE,
  });

  return (
    <div className="bg-slate-900 text-white min-h-screen flex flex-col items-center justify-center font-sans p-4">
      <div className="bg-slate-800 p-6 md:p-8 rounded-2xl shadow-2xl shadow-slate-950/50 border border-slate-700 w-full max-w-md">
        <header className="text-center mb-6">
          <p className="text-slate-400 mt-2">
            Select two Mistermoon tiles to swap them.
          </p>
        </header>

        {/* Puzzle Board */}
        <div
          className="grid gap-2 p-2 bg-slate-900/50 rounded-lg border border-slate-700"
          style={{
            gridTemplateColumns: `repeat(${GRID_SIZE}, 1fr)`,
            width: "100%",
            aspectRatio: "1 / 1",
          }}
        >
          {tiles.map((tileValue, index) => {
            const isSelected = index === selectedTileIndex;
            return (
              <button
                key={tileValue}
                onClick={() => {
                  handleTileClick(index);
                }}
                type="button" // Add this for semantic correctness
                className={`rounded-md transition-all duration-300 ease-in-out flex items-center justify-center text-3xl md:text-4xl font-bold select-none bg-indigo-600 cursor-pointer shadow-md
        ${!isSolved ? "hover:scale-105 hover:z-10 hover:shadow-lg hover:bg-indigo-700" : ""}
        ${isSelected ? "ring-4 ring-amber-400 scale-105 z-10" : ""}
    `}
                style={{
                  backgroundImage: `url(${PIECES[tileValue - 1]})`,
                  backgroundSize: "cover",
                  backgroundPosition: "center",
                }}
              >
                {/* Any child content would go here */}
              </button>
            );
          })}
        </div>

        {/* Win Message and Shuffle Button */}
        <footer className="mt-6 text-center">
          {isSolved && (
            <div className="mb-4 p-3 bg-green-500/20 text-green-300 rounded-lg text-lg transition-opacity duration-500">
              🎉 You solved it! 🎉
            </div>
          )}
          {!isSolved && (
            <button
              onClick={handleShuffle}
              className="w-full bg-indigo-600 hover:bg-indigo-700 text-white font-bold py-3 px-4 rounded-lg text-lg transition-all duration-300 focus:outline-none focus:ring-4 focus:ring-indigo-500/50 shadow-lg hover:shadow-indigo-600/40"
            >
              Shuffle
            </button>
          )}
        </footer>
      </div>
    </div>
  );
};
