import { createRoot } from "react-dom/client";
import { SwapPuzzle } from "./SwapPuzzleComponent";

const swap_puzzle_elem = document.getElementById("swap-puzzle-root");
if (swap_puzzle_elem) {
  const root = createRoot(swap_puzzle_elem);
  root.render(
    <SwapPuzzle
      onVerify={(isVerified) => {
        console.log(isVerified);
      }}
    />,
  );
} else {
  console.error(
    "Could not mount because #swap-puzzle-root was nowhere to be found",
  );
}
